export function total(order) {                 // composed: outline only
  if (!isValid(order)) return Money.zero();
  return applyDiscount(subtotal(order), order.discount);
}

function isValid(order) { return order.lines.length > 0; }
function subtotal(order) {
  return order.lines.reduce((sum, line) => sum + line.amount, Money.zero());
}
function applyDiscount(total, discount) { return total.minus(discount); }
